/* ---------------------------------------------------------------- 取词函数 */
window.LE.pt = function (page, key, vars) {
  const pack = window.LE_PAGES[page];
  if (!pack) return key;
  const lang = window.LE.lang();
  const dict = pack[lang] || pack.zh;
  let out = dict[key] != null ? dict[key] : (pack.zh[key] != null ? pack.zh[key] : key);
  if (vars) Object.keys(vars).forEach((k) => { out = out.split('{' + k + '}').join(vars[k]); });
  return out;
};

/** 页面级标记：把 **粗体** 语法转成 <strong>，其余转义。 */
window.LE.rich = function (text) {
  return window.LE.esc(text).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
};
